console.log(`till ${dl[0]}..${dl[dl.length - 1]} (${sales.length - 1} rows): takings ${takings}, sold ${sold}, waste ${waste}, top waste ${topWaste} ${topWasteN}; late: ${late.join(", ")}`);

// ---------- 7. Menu page ----------
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
